use std::error::Error;
use std::fmt;

use security_framework::access_control::{ProtectionMode, SecAccessControl};
use security_framework::item::{ItemSearchOptions, KeyClass, Location, Reference, SearchResult};
use security_framework::key::{Algorithm, GenerateKeyOptions, KeyType, SecKey, Token};
use security_framework_sys::access_control::kSecAccessControlPrivateKeyUsage;

/// The protection used to create a P-256 private key.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[non_exhaustive]
pub enum KeyBackend {
    /// A non-exportable key generated by the Secure Enclave.
    SecureEnclave,
    /// A non-exportable key in the login Keychain, with the creating app's ACL.
    AppRestrictedKeychain,
    /// An existing key loaded by label; its original storage is not exposed here.
    Existing,
}

/// A Security.framework error with its stable `OSStatus` code.
#[derive(Clone, Debug, Eq, PartialEq)]
#[non_exhaustive]
pub struct PlatformError {
    /// The operation that failed.
    pub operation: &'static str,
    /// The `OSStatus` or `CFError` code returned by Security.framework.
    pub code: i32,
}

impl fmt::Display for PlatformError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            formatter,
            "{} failed with OSStatus {}",
            self.operation, self.code
        )
    }
}

impl Error for PlatformError {}

/// A protected P-256 private key. Only public-key export and signing are exposed.
#[derive(Debug)]
pub struct ProtectedP256Key {
    key: SecKey,
    backend: KeyBackend,
    secure_enclave_error: Option<PlatformError>,
}

impl ProtectedP256Key {
    /// Loads `label` or creates a persistent P-256 signing key with that label.
    ///
    /// Creation first attempts the Secure Enclave with private-key-only access
    /// control. If that fails, it attempts a key in the default file-based login
    /// Keychain, whose default ACL is limited to the creating application. This
    /// method never deletes or replaces an existing key.
    ///
    /// # Errors
    ///
    /// Returns an error if the label is empty, lookup fails, both creation
    /// attempts fail, or an existing key cannot be loaded.
    pub fn create_or_load(label: &str) -> Result<Self, KeyError> {
        if label.trim().is_empty() {
            return Err(KeyError::EmptyLabel);
        }

        if let Some(key) = find_private_key(label)? {
            return Ok(Self {
                key,
                backend: KeyBackend::Existing,
                secure_enclave_error: None,
            });
        }

        match generate(
            label,
            Token::SecureEnclave,
            Location::DataProtectionKeychain,
        ) {
            Ok(key) => Ok(Self {
                key,
                backend: KeyBackend::SecureEnclave,
                secure_enclave_error: None,
            }),
            Err(secure_enclave_error) => {
                let key = generate(label, Token::Software, Location::DefaultFileKeychain).map_err(
                    |fallback| KeyError::Creation {
                        secure_enclave: secure_enclave_error.clone(),
                        fallback,
                    },
                )?;
                Ok(Self {
                    key,
                    backend: KeyBackend::AppRestrictedKeychain,
                    secure_enclave_error: Some(secure_enclave_error),
                })
            }
        }
    }

    /// Returns the storage selected by this creation or lookup operation.
    #[must_use]
    pub const fn backend(&self) -> KeyBackend {
        self.backend
    }

    /// Returns the Secure Enclave error that caused fallback creation, if any.
    #[must_use]
    pub const fn secure_enclave_error(&self) -> Option<&PlatformError> {
        self.secure_enclave_error.as_ref()
    }

    /// Returns the public key as an uncompressed SEC1 point.
    ///
    /// # Errors
    ///
    /// Returns an error if Security.framework cannot supply the public key or
    /// its external representation.
    pub fn public_key_sec1(&self) -> Result<Vec<u8>, KeyError> {
        let public_key = self.key.public_key().ok_or(KeyError::MissingPublicKey)?;
        public_key
            .external_representation()
            .map(|data| data.to_vec())
            .ok_or(KeyError::MissingPublicKey)
    }

    /// Signs a message using ECDSA with SHA-256 and returns a DER signature.
    ///
    /// # Errors
    ///
    /// Returns an error if access is denied or Security.framework cannot sign.
    pub fn sign(&self, message: &[u8]) -> Result<Vec<u8>, KeyError> {
        self.key
            .create_signature(Algorithm::ECDSASignatureMessageX962SHA256, message)
            .map_err(|error| {
                KeyError::Signing(PlatformError::new_cf("signing", error.code(), error))
            })
    }
}

/// A protected-key creation, lookup, public-key export, or signing failure.
#[derive(Clone, Debug, Eq, PartialEq)]
#[non_exhaustive]
pub enum KeyError {
    /// A stable, non-empty key label is required.
    EmptyLabel,
    /// Keychain lookup failed.
    Lookup(PlatformError),
    /// Both Secure Enclave and login-Keychain creation failed.
    Creation {
        /// The Secure Enclave failure.
        secure_enclave: PlatformError,
        /// The subsequent login-Keychain failure.
        fallback: PlatformError,
    },
    /// Security.framework did not provide a public key representation.
    MissingPublicKey,
    /// The keychain result was not a private key reference.
    UnexpectedSearchResult,
    /// Security.framework could not sign with the protected key.
    Signing(PlatformError),
}

impl fmt::Display for KeyError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::EmptyLabel => formatter.write_str("the protected-key label must not be empty"),
            Self::Lookup(error) => write!(formatter, "protected-key lookup: {error}"),
            Self::Creation {
                secure_enclave,
                fallback,
            } => write!(
                formatter,
                "Secure Enclave creation failed ({secure_enclave}); login-Keychain fallback failed ({fallback})"
            ),
            Self::MissingPublicKey => {
                formatter.write_str("Security.framework did not provide a public key")
            }
            Self::UnexpectedSearchResult => {
                formatter.write_str("Keychain lookup did not return a private key reference")
            }
            Self::Signing(error) => write!(formatter, "protected-key signing: {error}"),
        }
    }
}

impl Error for KeyError {}

impl PlatformError {
    fn new(operation: &'static str, code: i32, _error: impl fmt::Display) -> Self {
        Self { operation, code }
    }

    fn new_cf(operation: &'static str, code: isize, error: impl fmt::Display) -> Self {
        Self::new(operation, i32::try_from(code).unwrap_or(i32::MIN), error)
    }
}

fn access_control() -> Result<SecAccessControl, KeyError> {
    SecAccessControl::create_with_protection(
        Some(ProtectionMode::AccessibleWhenUnlockedThisDeviceOnly),
        kSecAccessControlPrivateKeyUsage,
    )
    .map_err(|error| {
        KeyError::Lookup(PlatformError::new(
            "access-control creation",
            error.code(),
            error,
        ))
    })
}

fn generate(label: &str, token: Token, location: Location) -> Result<SecKey, PlatformError> {
    let mut options = GenerateKeyOptions::default();
    options
        .set_key_type(KeyType::ec_sec_prime_random())
        .set_size_in_bits(256)
        .set_label(label)
        .set_location(location);
    if matches!(&token, Token::SecureEnclave) {
        let access = access_control().map_err(|error| match error {
            KeyError::Lookup(error) => error,
            _ => PlatformError::new("access-control creation", 0, error),
        })?;
        options.set_access_control(access);
    }
    options.set_token(token);
    SecKey::new(&options)
        .map_err(|error| PlatformError::new_cf("P-256 key generation", error.code(), error))
}

fn find_private_key(label: &str) -> Result<Option<SecKey>, KeyError> {
    let search = ItemSearchOptions::new()
        .key_class(KeyClass::private())
        .label(label)
        .load_refs(true)
        .limit(1_i64)
        .search();
    let results = match search {
        Ok(results) => results,
        Err(error) if error.code() == security_framework_sys::base::errSecItemNotFound => {
            return Ok(None);
        }
        Err(error) => {
            return Err(KeyError::Lookup(PlatformError::new(
                "key lookup",
                error.code(),
                error,
            )));
        }
    };
    let Some(result) = results.into_iter().next() else {
        return Ok(None);
    };
    match result {
        SearchResult::Ref(Reference::Key(key)) => Ok(Some(key)),
        _ => Err(KeyError::UnexpectedSearchResult),
    }
}
